#include <iostream>
#include <string>
#include <string_view>

class Employee {
public:
    // C++17 inline static member variable
    inline static unsigned int count{0};

    Employee(std::string_view first, std::string_view last)
        : firstName(first), lastName(last) {
        ++count;
        std::cout << "Employee constructor for " << firstName << ' ' << lastName << " called.\n";
    }

    ~Employee() {
        std::cout << "~Employee() called for " << firstName << ' ' << lastName << '\n';
        --count;
    }

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }

    // Static member function: cannot use 'this' and cannot be const
    static unsigned int getCount() {
        return count;
    }

private:
    std::string firstName;
    std::string lastName;
};

int main() {
    std::cout << "Number of employees before instantiation of any objects is "
              << Employee::getCount() << '\n';

    {
        Employee e1("Susan", "Baker");
        Employee e2("Robert", "Jones");

        std::cout << "Number of employees after objects are instantiated is "
                  << Employee::getCount() << "\n\n";

        std::cout << "Employee 1: " << e1.getFirstName() << " " << e1.getLastName() << '\n'
                  << "Employee 2: " << e2.getFirstName() << " " << e2.getLastName() << "\n\n";
    } // End of nested scope: e2 and e1 destroyed in reverse order

    std::cout << "\nNumber of employees after objects are deleted is "
              << Employee::getCount() << '\n';

    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

class BankAccount {
public:
    BankAccount(const std::string& owner, double initialBalance)
        : ownerName(owner) {
        if (!validateAmount(initialBalance)) {
            throw std::invalid_argument("Initial balance cannot be negative.");
        }
        balance = initialBalance;
    }

    ~BankAccount() {
        // Termination housekeeping: log account closure
        std::cout << "Account for " << ownerName << " closed successfully.\n";
    }

    // Access function (getter)
    double getBalance() const { return balance; }

    // Predicate access function
    bool hasFunds() const { return balance > 0.0; }

    void deposit(double amount) {
        if (validateAmount(amount)) {
            balance += amount;
        }
    }

    // Const reference return: preserves encapsulation
    const std::string& getOwner() const { return ownerName; }

private:
    std::string ownerName;
    double balance{0.0};

    // Utility function (private helper)
    bool validateAmount(double amount) const {
        return amount >= 0.0;
    }
};

int main() {
    try {
        BankAccount acc("Alice", 150.0);
        std::cout << "Owner: " << acc.getOwner() << " | Balance: $" << acc.getBalance() << '\n';
        std::cout << "Has funds: " << (acc.hasFunds() ? "true" : "false") << '\n';
        acc.deposit(50.0);
        std::cout << "Updated Balance: $" << acc.getBalance() << '\n';
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }
    return 0;
}
